import React,{useState}from'react';import{createRoot}from'react-dom/client';import{MemoryRouter,Routes,Route}from'react-router-dom';
import '../../src/index.css';import{AuthProvider}from'../../src/context/AuthContext';import Layout from'../../src/components/Layout';
import OperationalProjectDetail from'../../src/pages/OperationalProjectDetail';import OperationalProjects from'../../src/pages/OperationalProjects';
import{RunDeck,FrameDialog}from'../../src/components/operational-projects/RunDeck';import{feedOf}from'../../src/components/operational-projects/run-deck-logic';
import{ConfirmDialog,ApprovalDialog}from'../../src/components/operational-projects/AgentRuns';import{LIVE_TEXT}from'../../src/components/operational-projects/agent-run-text';
const id='11111111-1111-4111-8111-111111111111',guide='22222222-2222-4222-8222-222222222222',sha='a'.repeat(64),at='2026-10-02T21:00:00Z';
const project={id,name:'Selected operation',owner_user_id:1,owner_name:'fixture-owner',own_role:'owner',revision:1,current_version:{id:guide,title:'Approved fixture guide',version_number:1,content_hash:sha},description:'Read-only fixture',archived_at:null,visibility:'private'};
const projects=Array.from({length:25},(_,i)=>({...project,id:i?`${String(i).padStart(8,'0')}-1111-4111-8111-111111111111`:id,name:`Permitted project ${i+1}`}));
const frame={png_base64:'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/N1EAAAAASUVORK5CYII=',width:640,height:400,captured_at:at,action_count:1};
const run={id:'33333333-3333-4333-8333-333333333333',profile_name:'Demo sign-in fixture',state:'running',started_by:{id:1,username:'fixture-owner'},started_at:at,action_count:1,max_actions:20,guide_version_id:guide,guide_version_number:1,guide_hash:sha,help:null};
const data={run,origin:null,result:null,approvals:[],controls:{stop:{enabled:true},view:{enabled:true},takeover:{enabled:false,reason:'Fixture has no installed controller'},live:{enabled:false}},events:Array.from({length:50},(_,i)=>({id:i,kind:'running',created_at:at})),steps:[{ordinal:1,action:'open_landing',state:'done',decided_by:'rule',rule:'start',created_at:at,finished_at:at}],model_calls:[],reconciliation:{items:[]},critique:null,summary:null};
const options=new URLSearchParams(location.search),ended=options.get('mode')==='ended',video=options.get('transport')==='live';
const holder=options.get('control')==='held',populated=options.get('content')==='populated';
if(holder)data.controls.takeover={enabled:false,holder:{user_id:1,user:'fixture-owner',since:at}};
if(populated){data.run.help={open:true,result_class:'uncertain_step',uncertain_steps:8};data.reconciliation.items=Array.from({length:8},(_,i)=>({subject:`step:${i+1}`,kind:i%2?'write':'read',ordinal:i+1,action:'submit_bound_fixture',reason:'uncertain',open:true,gates:true,state:'unresolved'}));data.approvals=[{id:'fixture-approval',open:true,action:'submit_bound_fixture',digest:sha,requested_at:at}];}
if(ended){data.run={...data.run,state:'completed',awaiting_approval:true};data.controls.stop={enabled:false,reason:'This run has ended'};data.controls.view={enabled:false,reason:'This run has ended'};data.approvals=[{id:'historical-approval',open:true,action:'submit_bound_fixture',digest:sha,requested_at:at,state:'consumed'}];}
if(video){data.controls.live.enabled=true;window.fixtureLiveConnections=0;window.WebSocket=class{constructor(){window.fixtureLiveConnections++;this.readyState=1;setTimeout(()=>this.onmessage?.({data:JSON.stringify({type:'unavailable',code:'FIXTURE_NO_LIVE_SITE'})}),0);}send(){}close(){this.readyState=3;}};}
window.fixtureCalls=[];window.fetch=async(url,options={})=>{window.fixtureCalls.push(String(url));if(!String(url).startsWith('/api/'))throw new Error('External contact forbidden');let value={};const path=String(url).replace('/api','');
if(path==='/auth/verify')value={user:{id:1,username:'fixture-owner',role:'admin',permissions:[]}};
else if(path==='/operational-projects/capabilities')value={enabled:true,ui_available:true,agents_metadata_enabled:true,agent_runs_enabled:true,can_manage_settings:false};
else if(path.startsWith('/operational-projects?')||path==='/operational-projects')value={projects,next_cursor:null};
else if(path==='/operational-projects/directory')value={projects:[],next_cursor:null};
else if(path===`/operational-projects/${id}`)value={project};
else if(path===`/operational-projects/${id}/draft`)value={draft:{title:'Fixture guide',instructions:'Saved instruction\n'.repeat(150),revision:1,status:'draft',pending_submission:null}};
else if(path===`/operational-projects/${id}/versions`)value={versions:[],next_cursor:null};
else if(path===`/operational-projects/${id}/runs`)value={runs:[],next_cursor:null};
else if(path.startsWith(`/operational-projects/${id}/events`))value={events:[],next_cursor:null};
else if(path===`/operational-projects/${id}/access`)value={members:[]};
else if(path.includes(`/versions/${guide}`))value={version:{id:guide,content_hash:sha,title:'Fixture guide',instructions:'Pinned line.\n'.repeat(200)}};
else if(path==='/operational-projects/agent-approvals')value={approvals:[],help_requests:[],next_before:null};
else if(path.includes('/notifications'))value={notifications:[],unread_count:0};else if(path==='/cves')value={cves:[]};
else if(path==='/version')value={version:'fixture'};else if(path==='/operational-projects/agent-inbox')value={items:[],next_before:null};
return new Response(JSON.stringify(value),{status:200,headers:{'Content-Type':'application/json'}});};
function Deck(){const[panel,setPanel]=useState('browser'),[tab,setTab]=useState('result'),[enlarged,setEnlarged]=useState(null),[confirming,setConfirming]=useState(false),[approving,setApproving]=useState(false);return <div className="operations-ui h-full min-h-0 flex flex-col"><RunDeck base={`/${id}`} data={data} feed={feedOf(data)} view={{live:ended?null:frame,thumbs:new Map(),last:null}} active={!ended} panel={panel} onPanel={setPanel} tab={tab} onTab={setTab} watch onWatch={()=>{}} busy={false} onFrame={setEnlarged} onBack={()=>{}} onStop={()=>{}} onRefresh={()=>{}} onReview={()=>setApproving(true)} onTakeover={()=>{}} onEndTakeover={()=>setConfirming(true)} onDecide={(subject,decision)=>{window.fixtureDecisions??=[];window.fixtureDecisions.push({subject,decision});}} me={1} message="Fixture approval status preserved below the browser" liveView={video?{mode:'live',state:'unavailable',base:`/${id}`,control:{mine:holder},onState:()=>{},onControl:()=>{},onViewer:()=>{}}:null}/>{approving&&<ApprovalDialog approval={data.approvals[0]} onClose={()=>setApproving(false)} onApproved={()=>setApproving(false)}/>} {enlarged&&<FrameDialog frame={enlarged} onClose={()=>setEnlarged(null)}/>} {confirming&&<ConfirmDialog title={LIVE_TEXT.endTitle} body={LIVE_TEXT.endBody} confirm={LIVE_TEXT.end} destructive busy={false} onClose={()=>setConfirming(false)} onConfirm={()=>{window.fixtureGiveBackConfirmed=true;setConfirming(false);}}/>}</div>;}
const kind=new URLSearchParams(location.search).get('surface')||'deck',initial=kind==='projects'?'/operational-projects':kind==='project'?`/operational-projects/${id}`:'/operational-projects/fixture-deck';
createRoot(document.getElementById('root')).render(<AuthProvider><MemoryRouter initialEntries={[initial]}><Routes><Route element={<Layout/>}><Route path="/operational-projects" element={<OperationalProjects/>}/><Route path="/operational-projects/:id" element={kind==='deck'?<Deck/>:<OperationalProjectDetail/>}/></Route></Routes></MemoryRouter></AuthProvider>);
